-- 001036_wiki_entity_seed.up.sql
-- Seeds real-world wiki entities so directory categories render listings:
--   * bank organizations (org_type='bank') bound to each country space
--   * scholarship rows bound via country_space_id
--   * embassies: Nigerian missions abroad + foreign missions in Nigeria
-- Idempotent via NOT EXISTS guards on natural keys.
